import { ActivityRepository } from '../repositories/activity-repository.js';
import { ActivityData } from '../domain/activity.js';
import { NotFoundError } from './errors.js';

export class UpdateActivityUseCase {
  constructor(private activityRepository: ActivityRepository) {}

  execute(id: string, input: { titulo?: string; vagas?: number }): ActivityData {
    const activity = this.activityRepository.findById(id);
    if (!activity) {
      throw new NotFoundError('Atividade não encontrada');
    }

    this.activityRepository.update(id, input);

    const updated = this.activityRepository.findById(id);
    if (!updated) {
      throw new NotFoundError('Atividade não encontrada');
    }

    return updated;
  }
}

